  if (!(await dropdownVisible(page))) {
    const toast = await page.locator(".tlui-toast__container").allInnerTexts().catch(() => []);
    throw new Error(`relation menu did not open; toasts: ${JSON.stringify(toast)}`);
  }
};

const clickExact = async (page, text) => {
  const btn = dropdown(page).locator("button").filter({ hasText: new RegExp(`^\\s*${text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*$`) }).first();
  await btn.click();
};

const pickerRows = async (page) => (await dropdown(page).locator("button").allInnerTexts()).map((t) => t.trim()).filter((t) => t.includes(" / "));

// Relation triplets from Global settings props (the store getDiscourseRelations reads).
const globalRelations = (page) =>
  page.evaluate(() => {
    const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
    const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/uid :block/string :block/props]}]", [":node/title", "roam/js/discourse-graph"]);
    const gb = (cfg?.[":block/children"] || []).find((c) => c[":block/string"] === "Global");
    return Object.entries(g(gb?.[":block/props"], "Relations") || {}).map(([id, r]) => ({ id: id.replace(/^:/, ""), label: g(r, "label"), complement: g(r, "complement"), source: g(r, "source"), destination: g(r, "destination") }));
  });

const grammarBlocks = (page) =>
  page.evaluate(() => {
    const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/uid :block/string {:block/children ...}]}]", [":node/title", "roam/js/discourse-graph"]);
    const grammar = (cfg?.[":block/children"] || []).find((c) => /^grammar$/i.test(c[":block/string"]));
    const rel = (grammar?.[":block/children"] || []).find((c) => /^relations$/i.test(c[":block/string"]));
    const val = (b, k) => (b[":block/children"] || []).find((c) => new RegExp(`^${k}$`, "i").test(c[":block/string"]))?.[":block/children"]?.[0]?.[":block/string"];
    return { relationsUid: rel?.[":block/uid"], blocks: (rel?.[":block/children"] || []).map((r) => ({ uid: r[":block/uid"], label: r[":block/string"], source: val(r, "source"), destination: val(r, "destination"), complement: val(r, "complement") })) };
  });

const storedRelations = (page, uids) =>
  page.evaluate(async (uids) => {
    const rows = await window.roamAlphaAPI.data.async.q(`[:find ?u ?d :where [?s :block/uid ?u] [?s :block/props ?p] [(get ?p :discourse-graph) ?d]]`);
    const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
    return rows
      .map(([u, d]) => ({ uid: u, sourceUid: g(d, "sourceUid"), destinationUid: g(d, "destinationUid"), hasSchema: g(d, "hasSchema") }))
      .filter((r) => uids.includes(r.sourceUid) || uids.includes(r.destinationUid));
  }, uids);

// Mirrors createRelationSchema: grammar block + Global.Relations entry.
const createTriplet = (page, t) =>
  page.evaluate(async ({ label, complement, source, destination, ifFrom }) => {
    const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/uid :block/string {:block/children [:block/uid :block/string]}]}]", [":node/title", "roam/js/discourse-graph"]);
    const grammar = (cfg?.[":block/children"] || []).find((c) => /^grammar$/i.test(c[":block/string"]));
    const rel = (grammar?.[":block/children"] || []).find((c) => /^relations$/i.test(c[":block/string"]));
    const gb = (cfg?.[":block/children"] || []).find((c) => c[":block/string"] === "Global");
    const uid = window.roamAlphaAPI.util.generateUID();
    const api = window.roamAlphaAPI.data.block;
    await api.create({ location: { "parent-uid": rel[":block/uid"], order: "last" }, block: { uid, string: label } });
    for (const [i, [k, v]] of [["source", source], ["destination", destination], ["complement", complement]].entries()) {
      const cu = window.roamAlphaAPI.util.generateUID();
      await api.create({ location: { "parent-uid": uid, order: i }, block: { uid: cu, string: k } });
      await api.create({ location: { "parent-uid": cu, order: 0 }, block: { string: v } });
    }
    const norm = (p) => (p && typeof p === "object" && !Array.isArray(p) ? Object.fromEntries(Object.entries(p).map(([k, v]) => [k.replace(/^:+/, ""), norm(v)])) : Array.isArray(p) ? p.map(norm) : p);
    const raw = window.roamAlphaAPI.pull("[:block/props]", [":block/uid", gb[":block/uid"]])?.[":block/props"] || {};
    const props = norm(raw);
    const ifConditions = ifFrom ? JSON.parse(JSON.stringify(props.Relations?.[ifFrom]?.ifConditions || [])) : [];
    props.Relations = { ...(props.Relations || {}), [uid]: { label, source, destination, complement, ifConditions } };
    await api.update({ block: { uid: gb[":block/uid"], props } });
    return uid;
  }, t);

// Mirrors deleteRelationSchema for every triplet whose complement carries the marker.
const deleteMarkedTriplets = (page) =>
  page.evaluate(async (mark) => {
    const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
    const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/uid :block/string :block/props {:block/children ...}]}]", [":node/title", "roam/js/discourse-graph"]);
    const grammar = (cfg?.[":block/children"] || []).find((c) => /^grammar$/i.test(c[":block/string"]));
    const rel = (grammar?.[":block/children"] || []).find((c) => /^relations$/i.test(c[":block/string"]));
    const val = (b, k) => (b[":block/children"] || []).find((c) => new RegExp(`^${k}$`, "i").test(c[":block/string"]))?.[":block/children"]?.[0]?.[":block/string"];
    const blocks = (rel?.[":block/children"] || []).filter((r) => (val(r, "complement") || "").includes(mark) || (r[":block/string"] || "").includes(mark));
    const deletedBlocks = [];
    for (const b of blocks) { await window.roamAlphaAPI.data.block.delete({ block: { uid: b[":block/uid"] } }); deletedBlocks.push(`${b[":block/uid"]}|${b[":block/string"]}|${val(b, "complement")}`); }
    const gb = (cfg?.[":block/children"] || []).find((c) => c[":block/string"] === "Global");
    const norm = (p) => (p && typeof p === "object" && !Array.isArray(p) ? Object.fromEntries(Object.entries(p).map(([k, v]) => [k.replace(/^:+/, ""), norm(v)])) : Array.isArray(p) ? p.map(norm) : p);
    const raw = window.roamAlphaAPI.pull("[:block/props]", [":block/uid", gb[":block/uid"]])?.[":block/props"] || {};
    const props = norm(raw);
    const deletedGlobal = [];
    for (const [id, r] of Object.entries(props.Relations || {})) {
      if ((r.complement || "").includes(mark) || (r.label || "").includes(mark)) { delete props.Relations[id]; deletedGlobal.push(`${id}|${r.label}|${r.complement}`); }
    }
    if (deletedGlobal.length) await window.roamAlphaAPI.data.block.update({ block: { uid: gb[":block/uid"], props } });
    return { deletedBlocks, deletedGlobal };
  }, MARK);

const recorder = (outDir) => {
  const out = {};
  const flush = () => fs.writeFileSync(`${outDir}/eng2243-result.json`, JSON.stringify(out, null, 2));
  const step = async (name, fn) => {
    try { out[name] = await fn(); } catch (e) { out[name] = { error: String(e?.message || e).slice(0, 600) }; }
    flush();
    return out[name];
  };
  return { out, step, flush };
};

export default {
  async ready({ page }) {
    await closeDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const logs = [];
    page.on("console", (m) => { if (["error", "warning"].includes(m.type())) logs.push(`[${m.type()}] ${m.text().slice(0, 250)}`); });
    page.on("pageerror", (e) => logs.push(`[pageerror] ${String(e?.message || e).slice(0, 250)}`));
    const { out, step } = recorder(outDir);
    out.shots = {};

    out.preexistingMarked = (await globalRelations(page)).filter((r) => `${r.label}${r.complement}`.includes(MARK)).length;
    if (out.preexistingMarked) throw new Error("marker already present in relations; refusing to run");

    // Stored relations setting as shown in the settings UI.
    out.storedRelationsSetting = await step("storedRelationsSetting", async () => {
      await page.keyboard.press("Meta+p");
      await sleep(page, 700);
      await page.keyboard.type("DG: Open - Discourse settings");
      await sleep(page, 700);
      await page.keyboard.press("Enter");
      await sleep(page, 2000);
      const label = page.locator("label", { hasText: "Enable stored relations" }).first();
      const found = await label.count();
      const checked = found ? await label.locator("input").isChecked().catch(() => null) : null;
      await closeDialogs(page);
      return { found, checked };
    });

    if (out.storedRelationsSetting?.checked !== true) throw new Error(`stored relations setting not ON: ${JSON.stringify(out.storedRelationsSetting)}`);
    // Fixtures: T0 (unrelated pair, unique label), T1 X->Y "supports", T2 Y->X "supports".
    out.fixtures = await step("fixtures", async () => {
      // Legacy mode drops triplets without if-conditions, so borrow the Evidence->Claim Supports pattern.
      const ifFrom = out.storedRelationsSetting?.checked ? undefined : "2CcUT958c";
      const T0 = await createTriplet(page, { label: L0, complement: C0, source: NODE.result, destination: NODE.test, ifFrom });
      // New Relations keys tend to list first, so create T2 before T1.
      const T2 = await createTriplet(page, { label: "supports", complement: C2, source: NODE.consequence, destination: NODE.conclusion, ifFrom });
      let T1 = await createTriplet(page, { label: "supports", complement: C1, source: NODE.conclusion, destination: NODE.consequence, ifFrom });
      // Old code took the first same-label match, so only T1-before-T2 order can expose the bug; re-roll T2's uid.
      let orderTries = 0;
      for (; orderTries < 40; orderTries += 1) {
        const ids = (await globalRelations(page)).map((r) => r.id);
        if (ids.indexOf(T1) < ids.indexOf(T2)) break;
        await deleteTripletById(page, T1);
        T1 = await createTriplet(page, { label: "supports", complement: C1, source: NODE.conclusion, destination: NODE.consequence, ifFrom });
      }
      const fmt = await page.evaluate(() => {
        const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
        const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/string :block/props]}]", [":node/title", "roam/js/discourse-graph"]);
        const gb = (cfg?.[":block/children"] || []).find((c) => c[":block/string"] === "Global");
        return g(gb?.[":block/props"], "Canvas page format");
      });
      const canvasTitle = (fmt && fmt.includes("*") ? fmt : "Canvas/*").replace("*", `${MARK} canvas ${TS}`);
      const titles = {
        canvas: canvasTitle,
        q: `${MARK} question ${TS}`, h: `${MARK} hypothesis ${TS}`,
        x: `${MARK} conclusion X ${TS}`, y: `${MARK} consequence Y ${TS}`,
      };
      const uids = {};
      for (const [k, t] of Object.entries(titles)) {
        uids[k] = window_uid();
        await page.evaluate(({ t, u }) => window.roamAlphaAPI.data.page.create({ page: { title: t, uid: u } }), { t, u: uids[k] });
      }
      await sleep(page, 1500);
      const order = (await globalRelations(page)).map((r) => r.id).filter((id) => [T1, T2].includes(id));
      return { T0, T1, T2, orderTries, T1BeforeT2InGlobalOrder: order[0] === T1, titles, uids };
    });
    const F = out.fixtures;
    if (F.error) throw new Error(F.error);
    const nodeUids = [F.uids.q, F.uids.h, F.uids.x, F.uids.y];

    await step("openCanvas", async () => {
      await page.evaluate((u) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid: u } }), F.uids.canvas);
      await installEditorFinder(page);
      const start = Date.now();
      while (Date.now() - start < 60000) {
        if (await page.evaluate(() => Boolean(window.__e2243Ed?.())).catch(() => false)) break;
        await sleep(page, 300);
      }
      await closeDialogs(page);
      await page.evaluate((n) => {
        const ed = window.__e2243Ed();
        ed.createShapes([
          { id: "shape:q", type: "discourse-node", x: 0, y: 0, props: { uid: n.q.uid, title: n.q.title, nodeTypeId: n.q.type, w: 220, h: 90 } },
          { id: "shape:h", type: "discourse-node", x: 600, y: 0, props: { uid: n.h.uid, title: n.h.title, nodeTypeId: n.h.type, w: 220, h: 90 } },
          { id: "shape:x", type: "discourse-node", x: 0, y: 400, props: { uid: n.x.uid, title: n.x.title, nodeTypeId: n.x.type, w: 220, h: 90 } },
          { id: "shape:y", type: "discourse-node", x: 600, y: 400, props: { uid: n.y.uid, title: n.y.title, nodeTypeId: n.y.type, w: 220, h: 90 } },
        ]);
        ed.zoomToFit();
        const cam = ed.getCamera();
        ed.setCamera({ ...cam, y: cam.y - 140 / cam.z });
        return true;
      }, {
        q: { uid: F.uids.q, title: F.titles.q, type: NODE.question },
        h: { uid: F.uids.h, title: F.titles.h, type: NODE.hypothesis },
        x: { uid: F.uids.x, title: F.titles.x, type: NODE.conclusion },
        y: { uid: F.uids.y, title: F.titles.y, type: NODE.consequence },
      });
      await sleep(page, 1500);
      return page.evaluate(() => window.__e2243Ed().getCurrentPageShapes().map((s) => `${s.id}|${s.props?.nodeTypeId}`));
    });

    if (!out.storedRelationsSetting?.checked) throw new Error("stored relations setting reads OFF; stopping");

    // Scenario 2: Escape leaves the picker, then closes the menu (Question -> Hypothesis, empty pair).
    out.s2 = await step("s2", async () => {
      await dragHandle(page, "shape:q", "shape:h");
      const emptyState = await dropdownText(page);
      await clickExact(page, "Add existing…");
      await sleep(page, 400);
      const pickerText = await dropdownText(page);
      await page.keyboard.press("Escape");
      await sleep(page, 400);
      const afterFirstEscape = await dropdownText(page);
      await page.keyboard.press("Escape");
      await sleep(page, 400);
      const visibleAfterSecond = await dropdownVisible(page);
      return {
        emptyState, pickerHasBack: pickerText?.includes("‹"), afterFirstEscape, visibleAfterSecond,
        pass: Boolean(pickerText?.includes("Question → Hypothesis") && afterFirstEscape?.includes("Add existing…") && !afterFirstEscape?.includes("→") && !visibleAfterSecond),
      };
    });

    // Scenario 1: empty pair -> Add existing… -> pick T0 type -> toast -> listed -> arrow + stored relation.
    out.s1 = await step("s1", async () => {
      await dragHandle(page, "shape:q", "shape:h");
      const emptyState = await dropdownButtons(page);
      await clickExact(page, "Add existing…");
      await sleep(page, 500);
      const header = await dropdown(page).locator("button[aria-label='Back to relation types']").locator("xpath=..").innerText();
      const rows = await pickerRows(page);
      out.shots.pickerEmptyPair = await shot(page, outDir, "eng2243-picker-empty-pair.png");
      await clickExact(page, `${L0} / ${C0}`);
      const toastLoc = page.locator(".tlui-toast__container").filter({ hasText: "Discourse relation added" }).first();
      await toastLoc.waitFor({ state: "visible", timeout: 10000 });
      await sleep(page, 700);
      const toastText = (await toastLoc.innerText()).replace(/\s+/g, " ").trim();
      out.shots.toast = await shot(page, outDir, "eng2243-toast.png");
      const toastVisibleAtShot = await toastLoc.isVisible();
      await sleep(page, 500);
      const listAfter = await dropdownButtons(page);
      out.shots.typeAdded = await shot(page, outDir, "eng2243-type-added.png");
      const created = (await globalRelations(page)).filter((r) => r.label === L0 && r.source === NODE.question && r.destination === NODE.hypothesis);
      const grammar = (await grammarBlocks(page)).blocks.filter((b) => b.label === L0 && b.source === NODE.question && b.destination === NODE.hypothesis);
      await clickExact(page, L0);
      await sleep(page, 5000);
      const arrows = await page.evaluate(() => window.__e2243Ed().getCurrentPageShapes().filter((s) => s.type !== "discourse-node").map((s) => ({ id: s.id, type: s.type, relationTypeId: s.props?.relationTypeId, text: s.props?.text })));
      const bindings = await page.evaluate(() => window.__e2243Ed().store.allRecords().filter((r) => r.typeName === "binding").map((b) => `${b.fromId}|${b.props?.terminal}|${b.toId}`));
      await page.evaluate(() => { window.__e2243Ed().selectNone(); return true; });
      await sleep(page, 400);
      out.shots.arrow = await shot(page, outDir, "eng2243-arrow-drawn.png");
      const stored = await storedRelations(page, [F.uids.q, F.uids.h]);
      const newId = created[0]?.id;
      const match = stored.filter((s) => s.hasSchema === newId && s.sourceUid === F.uids.q && s.destinationUid === F.uids.h);
      // Re-open the menu for the same pair: the added type is listed and no longer offered in the picker.
      await dragHandle(page, "shape:q", "shape:h");
      const listReopen = await dropdownButtons(page);
      const plus = dropdown(page).locator("button[aria-label='Add relation type']");
      let rowsReopen = null;
      if (await plus.count()) {
        await plus.click(); await sleep(page, 300);
        await clickExact(page, "Add existing…"); await sleep(page, 400);
        rowsReopen = await pickerRows(page);
      }
      await page.keyboard.press("Escape"); await sleep(page, 300);
      await page.keyboard.press("Escape"); await sleep(page, 300);
      const tripletsForPair = (await globalRelations(page)).filter((r) => r.label === L0 && r.source === NODE.question && r.destination === NODE.hypothesis).map((r) => r.id);
      const notOfferedAgain = Array.isArray(rowsReopen) && !rowsReopen.includes(`${L0} / ${C0}`);
      return { toastVisibleAtShot, listReopen, rowsReopen, notOfferedAgain, tripletsForPair,
        emptyState, header: header.replace(/\s+/g, " ").trim(), rowCount: rows.length, rowsSample: rows.slice(0, 40),
        t0Offered: rows.includes(`${L0} / ${C0}`), toastText, listAfter, createdTriplets: created, grammarBlocks: grammar,
        arrows, bindings, stored, matchingStored: match,
        pass: Boolean(toastText.includes(`${L0} added for Question and Hypothesis`) && listAfter.includes(L0) && created.length === 1 && grammar.length === 1 && grammar[0].uid === newId && arrows.some((a) => a.relationTypeId === newId) && match.length === 1 && notOfferedAgain && tripletsForPair.length === 1 && toastVisibleAtShot),
      };
    });

    // Scenario 4: pair with types (Conclusion -> Consequence) via "+" -> Add existing….
    out.s4 = await step("s4", async () => {
      await dragHandle(page, "shape:x", "shape:y");
      const list = await dropdownButtons(page);
      const plus = dropdown(page).locator("button[aria-label='Add relation type']");
      const plusCount = await plus.count();
      await plus.click();
      await sleep(page, 300);
      const actionMenu = await dropdownButtons(page);
      await clickExact(page, "Add existing…");
      await sleep(page, 500);
      const header = await dropdown(page).locator("button[aria-label='Back to relation types']").locator("xpath=..").innerText();
      const rows = await pickerRows(page);
      out.shots.pairWithTypes = await shot(page, outDir, "eng2243-pair-with-types.png");
      const shown = ["supports", C2];
      const leaked = rows.filter((r) => { const [l, c] = r.split(" / "); return shown.includes(l) || shown.includes(c); });
      await page.keyboard.press("Escape");
      await sleep(page, 300);
      await page.keyboard.press("Escape");
      await sleep(page, 300);
      return {
        list, plusCount, actionMenu, header: header.replace(/\s+/g, " ").trim(), rowCount: rows.length, rows,
        leaked, t0Offered: rows.includes(`${L0} / ${C0}`), caseVariantOffered: rows.filter((r) => /^supports \/|^Supports \//i.test(r)),
        closed: !(await dropdownVisible(page)),
        pass: Boolean(plusCount === 1 && leaked.length === 0 && rows.length > 0),
      };
    });

    // Scenario 3: same-label triplets; drag Y -> X, pick "supports" -> stored as T2 with source Y.
    out.s3 = await step("s3", async () => {
      await dragHandle(page, "shape:y", "shape:x");
      const list = await dropdownButtons(page);
      await clickExact(page, "supports");
      await sleep(page, 5000);
      const arrows = await page.evaluate(() => window.__e2243Ed().getCurrentPageShapes().filter((s) => s.type !== "discourse-node").map((s) => ({ id: s.id, type: s.type, relationTypeId: s.props?.relationTypeId, text: s.props?.text })));
      await page.evaluate(() => { window.__e2243Ed().selectNone(); return true; });
      await sleep(page, 400);
      out.shots.sameLabel = await shot(page, outDir, "eng2243-same-label-saved.png");
      const stored = await storedRelations(page, [F.uids.x, F.uids.y]);
      return {
        list, arrows, stored, expected: { hasSchema: F.T2, sourceUid: F.uids.y, destinationUid: F.uids.x },
        pass: stored.length === 1 && stored[0].hasSchema === F.T2 && stored[0].sourceUid === F.uids.y && stored[0].destinationUid === F.uids.x,
      };
    });

    out.errors = logs.filter((l) => !/create-space|Could not log in|ERR_CONNECTION_REFUSED|Failed to create space/.test(l)).slice(0, 30);
    fs.writeFileSync(`${outDir}/eng2243-result.json`, JSON.stringify(out, null, 2));
    return { s1: out.s1?.pass, s2: out.s2?.pass, s3: out.s3?.pass, s4: out.s4?.pass, result: `${outDir}/eng2243-result.json` };
  },
  async cleanup({ page, outDir }) {
    const res = {};
    await page.keyboard.press("Escape").catch(() => {});
    // Leave the canvas so its unmount cannot rewrite the page after deletion.
    await page.evaluate(() => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { title: "roam/js/discourse-graph" } })).catch(() => {});
    await sleep(page, 1500);
    const pages = await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find ?u ?t :where [?p :node/title ?t] [?p :block/uid ?u] [(clojure.string/includes? ?t "${mark}")]]`), MARK);
    const nodeUids = pages.map(([u]) => u);
    const stored = await storedRelations(page, nodeUids);
    for (const s of stored) await page.evaluate((u) => window.roamAlphaAPI.data.block.delete({ block: { uid: u } }), s.uid);
    res.deletedStoredRelations = stored.map((s) => `${s.uid}|${s.hasSchema}|${s.sourceUid}->${s.destinationUid}`);
    res.triplets = await deleteMarkedTriplets(page);
    for (const [u] of pages) await page.evaluate((u) => window.roamAlphaAPI.data.page.delete({ page: { uid: u } }), u);
    res.deletedPages = pages.map(([u, t]) => `${u}|${t}`);
    await sleep(page, 1500);
    // Blocks the legacy save path wrote onto pages we did not create (they reference our node titles).
    const strays = await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find ?u ?s :where [?b :block/string ?s] [?b :block/uid ?u] [(clojure.string/includes? ?s "${mark}")]]`), MARK);
    for (const [u] of strays) await page.evaluate((u) => window.roamAlphaAPI.data.block.delete({ block: { uid: u } }), u);
    res.deletedStrayBlocks = strays.map(([u, s]) => `${u}|${s.slice(0, 120)}`);
    await sleep(page, 2500);
    res.remaining = {
      pages: await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find (count ?p) . :where [?p :node/title ?t] [(clojure.string/includes? ?t "${mark}")]]`), MARK),
      blocks: await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find (count ?b) . :where [?b :block/string ?s] [(clojure.string/includes? ?s "${mark}")]]`), MARK),
