const LX = `${MARK} backs`;
const CX = `${MARK} backed by`;
const LN = `${MARK} informs`;
const CN = `${MARK} informed by`;
const LN2 = `${MARK} extends`;
const CN2 = `${MARK} extended by`;

const dialog = (page) => page.locator(".bp3-dialog").filter({ hasText: "Add relation type" }).first();
const dialogOpen = async (page) => (await dialog(page).count()) > 0 && (await dialog(page).isVisible());
const dialogError = async (page) => ((await dialog(page).locator(".text-red-700").count()) ? (await dialog(page).locator(".text-red-700").innerText()).trim() : null);
const fill = async (page, label, complement) => {
  await page.locator("#dg-new-relation-label").fill(label);
  await page.locator("#dg-new-relation-complement").fill(complement);
};
const continueBtn = (page) => dialog(page).locator("button", { hasText: "Continue" });
const toastTexts = (page) => page.locator(".tlui-toast__container").allInnerTexts().then((ts) => ts.map((t) => t.replace(/\s+/g, " ").trim())).catch(() => []);
const waitToast = (page, text) => page.locator(".tlui-toast__container").filter({ hasText: text }).first().waitFor({ state: "visible", timeout: 10000 });

export default {
  async ready({ page }) {
    await closeDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const logs = [];
    page.on("console", (m) => { if (["error", "warning"].includes(m.type())) logs.push(`[${m.type()}] ${m.text().slice(0, 250)}`); });
    page.on("pageerror", (e) => logs.push(`[pageerror] ${String(e?.message || e).slice(0, 250)}`));
    const { out, step } = recorder(outDir);
    out.shots = {};

    out.preexistingMarked = (await globalRelations(page)).filter((r) => `${r.label}${r.complement}`.includes(MARK)).length;
    if (out.preexistingMarked) throw new Error("marker already present in relations; refusing to run");

    out.storedRelationsSetting = await step("storedRelationsSetting", async () => {
      await page.keyboard.press("Meta+p");
      await sleep(page, 700);
      await page.keyboard.type("DG: Open - Discourse settings");
      await sleep(page, 700);
      await page.keyboard.press("Enter");
      await sleep(page, 2000);
      const label = page.locator("label", { hasText: "Enable stored relations" }).first();
      const found = await label.count();
      const checked = found ? await label.locator("input").isChecked().catch(() => null) : null;
      await closeDialogs(page);
      return { found, checked };
    });
    if (out.storedRelationsSetting?.checked !== true) throw new Error(`stored relations setting not ON: ${JSON.stringify(out.storedRelationsSetting)}`);

    // Fixtures: T0 on an unrelated pair (for validation), TX on Conclusion -> Consequence (pair with types).
    out.fixtures = await step("fixtures", async () => {
      const T0 = await createTriplet(page, { label: L0, complement: C0, source: NODE.result, destination: NODE.test });
      const TX = await createTriplet(page, { label: LX, complement: CX, source: NODE.conclusion, destination: NODE.consequence });
